SELECT id_usuario AS "IdUsuario",clave AS "Clave",fecha_vigencia AS "FechaVigencia",id_estado AS "IdEstado",intentos_conexion AS "IntentosConexion",fecha_bloqueo_temporal AS "FechaBloqueoTemporal",es_autorizado AS "EsAutorizado", tipo_entidad AS "TipoEntidad", id_entidad AS "IdEntidad",usuario_clientes AS "UsuarioClientes", usuario_negocios AS "UsuarioNegocios", usuario_servicios AS "UsuarioServicios", usuario_corredores AS "UsuarioCorredores",c1.valor as "Param_FechaSistema",c2.valor as "Param_IntentosMaximo",(now() AT TIME ZONE 'UTC') as "CurrentTimestamp",c3.valor AS "Param_ClaveUsuarioTiempoBloqueo" FROM t_pla_acc_usuario u LEFT JOIN t_pla_pla_configuracion c1 ON u.id_empresa = c1.id_empresa AND c1.codigo_parametro = 'PLA.FechaSistema' LEFT JOIN t_pla_pla_configuracion c2 ON u.id_empresa = c2.id_empresa AND c2.codigo_parametro = 'PLA.ClaveUsuarioIntentos' LEFT JOIN t_pla_pla_configuracion c3 ON u.id_empresa = c3.id_empresa AND c3.codigo_parametro = 'PLA.ClaveUsuarioTiempoBloqueo' WHERE u.id_empresa = :p_IdEmpresa AND codigo_usuario = :p_NombreUsuario